<?php declare(strict_types=1);function lh(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function lm(mixed $v):string{return number_format((float)$v,0,',',' ').' FCFA';}$labels=['a_analyser'=>'À analyser','approuve'=>'Validée','rejete'=>'Refusée','analyse'=>'Historique'];?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>File de validation FEB · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>.vl-shell{max-width:1320px}.vl-hero{padding:26px 28px;margin-bottom:18px;color:#fff;background:linear-gradient(120deg,var(--brand-primary),#3a3e77);border-radius:22px}.vl-hero h1{margin:0;color:#fff!important}.filters{padding:18px;margin-bottom:18px;background:#fff;border:1px solid var(--brand-border);border-radius:18px}.status-tabs{display:flex;gap:7px;flex-wrap:wrap}.feb-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.feb-card{display:flex;flex-direction:column;padding:19px;background:#fff;border:1px solid var(--brand-border);border-radius:18px;box-shadow:0 9px 28px #22254b0c}.feb-card header{display:flex;justify-content:space-between;gap:10px}.feb-card h2{margin:0;color:var(--brand-primary);font-size:1rem}.feb-card p{color:#777a8d;font-size:.76rem}.feb-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.feb-fact{padding:9px;background:#f7f7fa;border-radius:9px}.feb-fact small,.feb-fact strong{display:block}.feb-fact small{color:#858899;font-size:.6rem;text-transform:uppercase}.feb-card footer{margin-top:auto;padding-top:12px;border-top:1px solid #eee}.empty{grid-column:1/-1;padding:55px;text-align:center;background:#fff;border-radius:18px}@media(max-width:1000px){.feb-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.feb-grid{grid-template-columns:1fr}}</style></head><body class="module-page"><?php include APP_ROOT.'/partials/navbar.php';?><main class="container vl-shell"><header class="vl-hero"><h1><i class="fa-solid fa-list-check me-2 text-warning"></i>File de validation des FEB</h1><p class="mb-0 mt-2 text-white-50">Les décisions traitées quittent la file active et restent consultables dans l’historique.</p></header><?php if($flash):?><div class="alert alert-<?=lh($flash['type']??'info')?>"><?=lh($flash['message']??'')?></div><?php endif;?><form class="filters" method="get"><div class="row g-2"><div class="col-lg-8"><label class="form-label">Rechercher une FEB, un client, un BC, un devis ou un AO</label><input class="form-control" name="q" value="<?=lh($query)?>" placeholder="Ex. FEB-2026, FID-BC, nom du client…"></div><div class="col-lg-4 d-flex align-items-end gap-2"><button class="btn btn-primary flex-grow-1"><i class="fa-solid fa-search me-1"></i>Rechercher</button><a class="btn btn-outline-secondary" href="validation_feb.php">Effacer</a></div></div><div class="status-tabs mt-3"><?php foreach(['pending'=>'À traiter','all'=>'Toutes','approuve'=>'Validées','rejete'=>'Refusées'] as $value=>$label):?><a class="btn btn-sm <?=$status===$value?'btn-primary':'btn-outline-primary'?>" href="?<?=http_build_query(['q'=>$query,'status'=>$value])?>"><?=$label?></a><?php endforeach;?></div></form><section class="feb-grid"><?php foreach($filtered as $row):?><article class="feb-card"><header><div><h2><?=lh($row['numero_feb'])?></h2><small class="text-muted"><?=lh($row['document_uid'])?> · V<?=lh($row['document_version'])?></small></div><span class="badge text-bg-<?=$row['statut']==='approuve'?'success':($row['statut']==='rejete'?'danger':'warning')?>"><?=lh($labels[$row['statut']]??$row['statut'])?></span></header><p class="mt-3 mb-0"><strong><?=lh($row['nom_client'])?></strong><br><?=lh($row['num_offre'].' · '.$row['numero_devis'])?></p><div class="feb-facts"><div class="feb-fact"><small>Bon de commande</small><strong><?=lh($row['numero_bc'])?></strong></div><div class="feb-fact"><small>Montant demandé</small><strong><?=lm($row['montant_demande'])?></strong></div><div class="feb-fact"><small>Disponibilité</small><strong><?=date('d/m/Y',strtotime($row['date_disponibilite']))?></strong></div><div class="feb-fact"><small>Planning</small><strong><?=date('d/m/Y',strtotime($row['date_debut']))?> → <?=date('d/m/Y',strtotime($row['date_fin']))?></strong></div></div><footer><a class="btn <?=$row['statut']==='a_analyser'?'btn-success':'btn-outline-primary'?> w-100" href="validation_feb.php?feb_id=<?=(int)$row['id']?>"><i class="fa-solid <?=$row['statut']==='a_analyser'?'fa-magnifying-glass-check':'fa-eye'?> me-1"></i><?=$row['statut']==='a_analyser'?'Analyser la FEB':'Consulter le dossier'?></a></footer></article><?php endforeach;?><?php if(!$filtered):?><div class="empty"><i class="fa-regular fa-folder-open fa-2x mb-3"></i><h2>Aucune FEB trouvée</h2><p class="text-muted">Modifiez la recherche ou consultez l’historique.</p></div><?php endif;?></section></main></body></html>
